INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outgoing-1', 'outgoing', 'My best friend is really outgoing and can talk to anyone at a party.', '我最好的朋友特别外向,在派对上能和任何人聊天。', 'outgoing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sociable-1', 'sociable', 'I''m quite sociable, so I enjoy meeting new people at work.', '我挺好交际的,所以喜欢在工作中结识新朋友。', 'sociable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reserved-1', 'reserved', 'My dad is a bit reserved, but he''s very kind once you know him.', '我爸爸有点内敛,但熟悉之后你会发现他很和善。', 'reserved');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shy-1', 'shy', 'I was quite shy as a kid, so I rarely spoke up in class.', '我小时候挺害羞的,所以在课堂上很少发言。', 'shy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('easy-going-1', 'easy-going', 'My boss is very easy-going and never gets angry about small mistakes.', '我的老板很随和,从不为小错误生气。', 'easy-going');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('laid-back-1', 'laid-back', 'People in my hometown are pretty laid-back and never seem to hurry.', '我家乡的人都挺悠闲的,好像从来不着急。', 'laid-back');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('considerate-1', 'considerate', 'My neighbour is so considerate that she always turns her music down at night.', '我的邻居特别体贴,晚上总会把音乐调小。', 'considerate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thoughtful-1', 'thoughtful', 'It was really thoughtful of my friend to remember my mum''s birthday.', '我的朋友记得我妈妈的生日,真是太体贴了。', 'thoughtful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('generous-1', 'generous', 'My uncle is very generous and always pays when we go out for dinner.', '我叔叔很慷慨,我们出去吃饭总是他付钱。', 'generous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('selfish-1', 'selfish', 'I think it''s a bit selfish to play loud music late at night.', '我觉得深夜大声放音乐有点自私。', 'selfish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('modest-1', 'modest', 'Even though she''s won lots of prizes, my friend is very modest about it.', '虽然我朋友得过很多奖,但她对此很谦虚。', 'modest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('modest-2', 'modest', 'We live in a modest flat, but it''s enough for the two of us.', '我们住在一套不大的公寓里,但对我们两人来说够了。', 'modest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('humble-1', 'humble', 'He''s a famous doctor, but he''s really humble and friendly with everybody.', '他是一位名医,但待人特别谦逊友好。', 'humble');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arrogant-1', 'arrogant', 'I don''t like people who are arrogant about how much money they have.', '我不喜欢那些因为有钱就傲慢的人。', 'arrogant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('honest-1', 'honest', 'To me, the most important thing in a friend is being honest.', '对我来说,朋友最重要的品质是诚实。', 'honest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sincere-1', 'sincere', 'She''s a very sincere person, and I always believe what she says.', '她是一个非常真诚的人,我总是相信她说的话。', 'sincere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trustworthy-1', 'trustworthy', 'I''d only lend money to someone I know is really trustworthy.', '我只会把钱借给确实值得信赖的人。', 'trustworthy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('responsible-1', 'responsible', 'My older cousin is very responsible and always looks after the younger kids.', '我的表哥很负责任,总是照顾年纪小的孩子。', 'responsible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diligent-1', 'diligent', 'My classmate is so diligent that she checks every homework question twice.', '我的同学特别认真,每道作业题都检查两遍。', 'diligent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hard-working-1', 'hard-working', 'My parents are both hard-working people who taught me the value of money.', '我父母都是勤奋的人,他们教会了我金钱的价值。', 'hard-working');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('industrious-1', 'industrious', 'My grandparents were industrious farmers who got up before sunrise every day.', '我的祖父母是勤劳的农民,每天日出前就起床。', 'industrious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ambitious-1', 'ambitious', 'I''m quite ambitious, and I hope to run my own company one day.', '我挺有抱负的,希望有一天能经营自己的公司。', 'ambitious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('determined-1', 'determined', 'I was determined to pass my driving test, even after failing it twice.', '即使考了两次都没过,我还是下定决心要通过驾照考试。', 'determined');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('persistent-1', 'persistent', 'You have to be persistent if you want to learn a musical instrument.', '想学乐器就得坚持不懈。', 'persistent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('patient-1', 'patient', 'My piano teacher is incredibly patient and never gets tired of helping me.', '我的钢琴老师特别有耐心,从不厌烦帮助我。', 'patient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('optimistic-1', 'optimistic', 'I''m generally optimistic and try to see the good side of things.', '我总体上很乐观,尽量看到事情好的一面。', 'optimistic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pessimistic-1', 'pessimistic', 'I try not to be pessimistic, even when things aren''t going very well.', '即使事情不太顺利,我也尽量不悲观。', 'pessimistic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cheerful-1', 'cheerful', 'My roommate is always cheerful, even early in the morning.', '我的室友总是很开朗,就连大清早也一样。', 'cheerful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('humorous-1', 'humorous', 'My favourite teacher was very humorous, so her lessons were never boring.', '我最喜欢的老师很幽默,所以她的课从不无聊。', 'humorous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('witty-1', 'witty', 'He''s so witty that everyone laughs whenever he tells a story.', '他特别风趣,每次讲故事大家都会笑。', 'witty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('curious-1', 'curious', 'I''ve always been curious about how people live in other countries.', '我一直对其他国家的人怎样生活感到好奇。', 'curious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('open-minded-1', 'open-minded', 'Travelling abroad has made me much more open-minded about other cultures.', '出国旅行让我对其他文化的态度开明多了。', 'open-minded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('narrow-minded-1', 'narrow-minded', 'I think it''s narrow-minded to judge people by the way they dress.', '我觉得以衣着评判别人是心胸狭窄的表现。', 'narrow-minded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('independent-1', 'independent', 'Living away from home at university made me a lot more independent.', '上大学离家生活让我独立多了。', 'independent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mature-1', 'mature', 'My friend is very mature for her age and gives really good advice.', '我朋友比同龄人成熟得多,总能给出很好的建议。', 'mature');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sensible-1', 'sensible', 'My dad is a very sensible person, so I always ask him for advice.', '我爸爸是个很明智的人,所以我总是向他请教。', 'sensible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sensitive-1', 'sensitive', 'I''m quite sensitive, so I often get upset by what people say.', '我挺敏感的,所以常常因为别人的话而难过。', 'sensitive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('calm-1', 'calm', 'My mum stays calm even when something goes badly wrong at home.', '即使家里出了大问题,我妈妈也能保持冷静。', 'calm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('energetic-1', 'energetic', 'My little nephew is so energetic that he never seems to get tired.', '我的小侄子精力特别充沛,好像从来不会累。', 'energetic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enthusiastic-1', 'enthusiastic', 'Our new coach is really enthusiastic, which makes training a lot more fun.', '我们的新教练特别热情,这让训练有趣多了。', 'enthusiastic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('passionate-1', 'passionate', 'She''s passionate about teaching and spends her weekends preparing lessons.', '她对教学充满激情,周末都在备课。', 'passionate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adventurous-1', 'adventurous', 'I''m not very adventurous, so I usually order the same food every time.', '我不太爱冒险,所以每次都点同样的食物。', 'adventurous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cautious-1', 'cautious', 'I''m a cautious driver, especially when the roads are wet.', '我开车很谨慎,尤其是路面湿滑的时候。', 'cautious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decisive-1', 'decisive', 'A good leader needs to be decisive when things go wrong.', '出问题时,好的领导者需要果断。', 'decisive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stubborn-1', 'stubborn', 'My grandfather is so stubborn that he refuses to use a mobile phone.', '我爷爷特别固执,就是不肯用手机。', 'stubborn');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('knowledgeable-1', 'knowledgeable', 'My history teacher is really knowledgeable and can answer almost any question.', '我的历史老师知识渊博,几乎什么问题都能回答。', 'knowledgeable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('well-informed-1', 'well-informed', 'I read the news every morning because I like to stay well-informed.', '我每天早上看新闻,因为我喜欢保持消息灵通。', 'well-informed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('talented-1', 'talented', 'My friend is a really talented singer who has performed on television.', '我的朋友是一位很有才华的歌手,还上过电视。', 'talented');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('charismatic-1', 'charismatic', 'My favourite teacher was so charismatic that everyone listened whenever she spoke.', '我最喜欢的老师特别有魅力,她一开口大家都认真听。', 'charismatic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('influential-1', 'influential', 'My mum has been the most influential person in my life so far.', '到目前为止,我妈妈是对我人生最有影响力的人。', 'influential');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inspiring-1', 'inspiring', 'I find her story really inspiring because she started with almost nothing.', '我觉得她的故事很鼓舞人心,因为她几乎是白手起家。', 'inspiring');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('admirable-1', 'admirable', 'I think it''s admirable that she looks after her parents and works full-time.', '她既全职工作又照顾父母,我觉得令人钦佩。', 'admirable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('supportive-1', 'supportive', 'My family has always been very supportive of my decision to study abroad.', '我的家人一直很支持我出国留学的决定。', 'supportive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('approachable-1', 'approachable', 'My manager is very approachable, so I can ask her about anything.', '我的经理很平易近人,所以我什么都可以问她。', 'approachable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('strict-1', 'strict', 'My parents were quite strict with me when I was at school.', '我上学时,父母对我挺严格的。', 'strict');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('get-along-with-1', 'get-along-with', 'I get along with most of my colleagues, so work is pretty enjoyable.', '我和大多数同事相处融洽,所以工作挺愉快的。', 'get along with');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('capable-1', 'capable', 'She''s a very capable manager who always gets things done on time.', '她是一位很有能力的经理,总能按时把事情办好。', 'capable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alert-1', 'alert', 'I need a strong coffee in the morning to feel alert at work.', '我早上需要一杯浓咖啡,上班才觉得清醒警觉。', 'alert');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aspiring-1', 'aspiring', 'My cousin is an aspiring actor who goes to auditions almost every week.', '我的表弟是一位有抱负的演员,几乎每周都去试镜。', 'aspiring');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disciplined-1', 'disciplined', 'You have to be very disciplined to study on your own at home.', '要在家自学,你得非常自律。', 'disciplined');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dependable-1', 'dependable', 'He''s a really dependable friend who always turns up when he says he will.', '他是个非常可靠的朋友,说来就一定会来。', 'dependable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discreet-1', 'discreet', 'I can tell her any secret because she''s always very discreet.', '我什么秘密都可以告诉她,因为她总是很谨慎。', 'discreet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('expressive-1', 'expressive', 'My friend has a very expressive face, so I always know how she feels.', '我朋友的脸很有表现力,所以我总能看出她的感受。', 'expressive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('imaginative-1', 'imaginative', 'My son is very imaginative and loves making up his own stories.', '我儿子很有想象力,喜欢自己编故事。', 'imaginative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('faithful-1', 'faithful', 'Our old dog was a faithful friend to my family for fifteen years.', '我们的老狗十五年来一直是我们家忠实的朋友。', 'faithful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tolerant-1', 'tolerant', 'My parents are quite tolerant and let me make my own choices.', '我父母很宽容,让我自己作选择。', 'tolerant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('courageous-1', 'courageous', 'I think it was courageous of her to move abroad on her own.', '我觉得她独自出国很勇敢。', 'courageous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thrifty-1', 'thrifty', 'My mum is very thrifty and always looks for the cheapest prices.', '我妈妈很节俭,总是找最便宜的价格。', 'thrifty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('frugal-1', 'frugal', 'As a student, I had to be frugal and cook most of my meals.', '上学时我不得不节俭,大多自己做饭。', 'frugal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unselfish-1', 'unselfish', 'She''s the most unselfish person I know and always puts others first.', '她是我认识的最无私的人,总是把别人放在第一位。', 'unselfish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('frank-1', 'frank', 'To be frank, I don''t think I''d enjoy living in a big city.', '坦率地说,我觉得自己不会喜欢住在大城市。', 'frank');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outspoken-1', 'outspoken', 'My aunt is very outspoken and always says exactly what she thinks.', '我阿姨说话直言不讳,总是想什么就说什么。', 'outspoken');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('upright-1', 'upright', 'My grandfather was an upright man who never told a single lie.', '我爷爷是个正直的人,从没说过一句谎话。', 'upright');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('caring-1', 'caring', 'My mum is such a caring person, always worrying about everybody else.', '我妈妈是个很有爱心的人,总是为别人操心。', 'caring');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('affectionate-1', 'affectionate', 'Our cat is very affectionate and sleeps on my bed every night.', '我们的猫很黏人,每晚都睡在我床上。', 'affectionate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('charming-1', 'charming', 'He''s a charming man, and everyone at work seems to like him.', '他是个迷人的人,公司里每个人好像都喜欢他。', 'charming');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chatty-1', 'chatty', 'My neighbour is really chatty, so it takes ages to walk past her door.', '我的邻居特别健谈,所以经过她家门口总要聊好久。', 'chatty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('precocious-1', 'precocious', 'My niece is a precocious child who could read before she started school.', '我的侄女是个早熟的孩子,上学前就会读书了。', 'precocious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('respectable-1', 'respectable', 'My parents wanted me to have a respectable job like a doctor or teacher.', '我父母希望我有一份体面的工作,比如医生或老师。', 'respectable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mild-1', 'mild', 'My dad is a mild man who hardly ever raises his voice.', '我爸爸性情温和,几乎从不提高嗓门。', 'mild');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mild-2', 'mild', 'I only had a mild cold, so I still went to work.', '我只是轻微感冒,所以还是去上班了。', 'mild');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('passive-1', 'passive', 'I used to be quite passive in class and never asked any questions.', '我以前上课挺被动的,从不提问。', 'passive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conservative-1', 'conservative', 'My grandparents are quite conservative about what young people should wear.', '我的祖父母对年轻人的穿着观念挺保守的。', 'conservative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aggressive-1', 'aggressive', 'Some drivers in my city get really aggressive during the rush hour.', '我们城市的一些司机在高峰期特别有攻击性。', 'aggressive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cunning-1', 'cunning', 'The main character in the book is a cunning young man who tricks everyone.', '书里的主人公是个狡猾的年轻人,谁都骗。', 'cunning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('greedy-1', 'greedy', 'I felt a bit greedy after eating the last three pieces of cake.', '吃完最后三块蛋糕后,我觉得自己有点贪吃。', 'greedy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('indolent-1', 'indolent', 'I can get a bit indolent on holiday and just lie around all day.', '度假时我会有点懒,整天就躺着。', 'indolent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cowardly-1', 'cowardly', 'I felt cowardly for not telling my friend the truth.', '我没有告诉朋友真相,觉得自己很胆小。', 'cowardly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extravagant-1', 'extravagant', 'I think it''s extravagant to spend that much money on a pair of shoes.', '我觉得花那么多钱买一双鞋太奢侈了。', 'extravagant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('temperamental-1', 'temperamental', 'My boss can be quite temperamental, so we''re careful what we say.', '我的老板有时喜怒无常,所以我们说话很小心。', 'temperamental');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('optimist-1', 'optimist', 'I''m an optimist, so I always think that things will get better.', '我是个乐观主义者,总觉得事情会好起来。', 'optimist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pessimist-1', 'pessimist', 'My friend is a real pessimist who always expects the worst.', '我的朋友是个十足的悲观主义者,总是往最坏处想。', 'pessimist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('loyal-1', 'loyal', 'She''s been a loyal friend to me for more than twenty years.', '二十多年来,她一直是我忠诚的朋友。', 'loyal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suspicious-1', 'suspicious', 'My grandfather is a bit suspicious of anything he buys online.', '我爷爷对网上买的东西都有点疑心。', 'suspicious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suspicious-2', 'suspicious', 'I got a suspicious email last week, so I deleted it straight away.', '我上周收到一封可疑的邮件,就马上删掉了。', 'suspicious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eccentric-1', 'eccentric', 'My uncle is a bit eccentric and keeps dozens of birds in his flat.', '我叔叔有点古怪,在公寓里养了几十只鸟。', 'eccentric');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('genius-1', 'genius', 'I''m no genius at maths, but I can manage my own money.', '我不是数学天才,但能管好自己的钱。', 'genius');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brilliant-1', 'brilliant', 'My friend is a brilliant cook, and her food is better than any restaurant''s.', '我朋友是个杰出的厨师,她做的菜比任何餐馆都好吃。', 'brilliant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cynical-1', 'cynical', 'I''ve become a bit cynical about what politicians promise.', '我对政客的承诺变得有点愤世嫉俗了。', 'cynical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sceptical-1', 'sceptical', 'I''m sceptical about diets that promise quick results.', '我对那些承诺见效快的减肥法持怀疑态度。', 'sceptical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('companion-1', 'companion', 'My dog has been my faithful companion on long walks for years.', '多年来,我的狗一直是我长途散步的忠实同伴。', 'companion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('appearance-1', 'appearance', 'I don''t think you should judge people by their appearance.', '我认为不应该以貌取人。', 'appearance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attractive-1', 'attractive', 'I find people with a good sense of humour really attractive.', '我觉得有幽默感的人特别有吸引力。', 'attractive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('good-looking-1', 'good-looking', 'My cousin is very good-looking and could easily be a model.', '我表弟长得很好看,完全可以当模特。', 'good-looking');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('handsome-1', 'handsome', 'My dad was very handsome when he was young, judging by the photos.', '从照片看,我爸爸年轻时很英俊。', 'handsome');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elegant-1', 'elegant', 'My mum always looks elegant, even when she''s just going to the shops.', '我妈妈总是很优雅,即使只是去商店也一样。', 'elegant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('graceful-1', 'graceful', 'I love watching ballet because the dancers are so graceful.', '我喜欢看芭蕾,因为舞者们非常优美。', 'graceful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slim-1', 'slim', 'She''s tall and slim, with long dark hair and big brown eyes.', '她又高又苗条,一头乌黑的长发,棕色的大眼睛。', 'slim');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slender-1', 'slender', 'My friend has long, slender fingers, which are perfect for playing the piano.', '我朋友的手指又长又纤细,非常适合弹钢琴。', 'slender');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plump-1', 'plump', 'My grandmother was a plump, smiling woman who loved to cook for us.', '我奶奶是个丰满爱笑的人,很喜欢给我们做饭。', 'plump');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stocky-1', 'stocky', 'My uncle is short and stocky, but he''s really strong.', '我叔叔个子矮、身材壮实,但力气很大。', 'stocky');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('muscular-1', 'muscular', 'My brother-in-law goes to the gym every day and is very muscular.', '我的姐夫每天去健身房,肌肉很发达。', 'muscular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('athletic-1', 'athletic', 'She''s very athletic and plays almost every sport you can think of.', '她很健壮,几乎你能想到的运动她都玩。', 'athletic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('medium-height-1', 'medium-height', 'He''s of medium height, with short black hair and glasses.', '他中等身高,留着黑色短发,戴着眼镜。', 'medium height');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('complexion-1', 'complexion', 'She has a lovely clear complexion, even though she never wears make-up.', '她肤色清透好看,虽然从不化妆。', 'complexion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('freckles-1', 'freckles', 'As a child, I had lots of freckles on my nose and cheeks.', '我小时候鼻子和脸颊上有很多雀斑。', 'freckles');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wrinkle-1', 'wrinkle', 'My mum has a few wrinkles now, but her smile still looks young.', '我妈妈现在有几条皱纹了,但她的笑容依然年轻。', 'wrinkles');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('beard-1', 'beard', 'My dad has had a beard for as long as I can remember.', '从我记事起,我爸爸就留着胡须。', 'beard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('curly-1', 'curly', 'I''ve got curly hair, which is really hard to control in wet weather.', '我的头发是卷的,潮湿的天气里特别难打理。', 'curly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('straight-hair-1', 'straight-hair', 'My best friend has long straight hair down to her waist.', '我最好的朋友有一头齐腰的长直发。', 'straight hair');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ponytail-1', 'ponytail', 'She usually ties her hair back in a ponytail when she goes running.', '她跑步时通常把头发扎成马尾辫。', 'ponytail');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('casual-1', 'casual', 'I usually wear casual clothes like jeans and a T-shirt at weekends.', '周末我通常穿牛仔裤和 T 恤这样的休闲装。', 'casual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('formal-1', 'formal', 'I hardly ever wear formal clothes, except for weddings and interviews.', '除了婚礼和面试,我几乎不穿正式的衣服。', 'formal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fashionable-1', 'fashionable', 'I''m not very fashionable, and I just wear what feels comfortable.', '我不太时髦,穿舒服就行。', 'fashionable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trendy-1', 'trendy', 'There are lots of trendy cafés and shops in that part of town.', '城里那一带有很多新潮的咖啡馆和商店。', 'trendy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stylish-1', 'stylish', 'My aunt is always stylish, even though she doesn''t spend much on clothes.', '我阿姨总是很有型,虽然她在衣服上花钱不多。', 'stylish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outfit-1', 'outfit', 'I bought a new outfit for my best friend''s wedding last summer.', '去年夏天,我为最好朋友的婚礼买了一套新衣服。', 'outfit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accessory-1', 'accessory', 'A nice scarf is my favourite accessory because it goes with everything.', '漂亮的围巾是我最喜欢的配饰,因为它什么都能搭。', 'accessory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('forehead-1', 'forehead', 'He has a high forehead and looks a lot like his father.', '他的额头很高,长得很像他爸爸。', 'forehead');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eyebrow-1', 'eyebrow', 'My friend has really thick eyebrows, which make her look serious.', '我朋友的眉毛很浓,让她看起来很严肃。', 'eyebrows');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eyelash-1', 'eyelash', 'My baby niece has very long eyelashes, and everyone comments on them.', '我的小侄女睫毛很长,大家都夸。', 'eyelashes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('moustache-1', 'moustache', 'My grandfather wore a small moustache for most of his life.', '我爷爷一生大部分时间都留着小胡子。', 'moustache');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bald-1', 'bald', 'My dad started going bald when he was only about thirty.', '我爸爸才三十岁左右就开始秃头了。', 'bald');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blond-1', 'blond', 'My cousin has blond hair, which is quite unusual in my family.', '我的表妹是金发,这在我家很少见。', 'blond');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('skinny-1', 'skinny', 'I was really skinny as a teenager, no matter how much I ate.', '我十几岁时特别瘦,怎么吃都不胖。', 'skinny');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('feminine-1', 'feminine', 'She likes wearing feminine clothes, like long dresses and soft colours.', '她喜欢穿女性化的衣服,比如长裙和柔和的颜色。', 'feminine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('well-built-1', 'well-built', 'The new security guard at my office is tall and well-built.', '我们办公室新来的保安又高又壮。', 'well-built');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('well-dressed-1', 'well-dressed', 'My manager is always well-dressed, even on casual Fridays at work.', '我的经理总是穿着讲究,哪怕是公司的休闲星期五也一样。', 'well-dressed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('masculine-1', 'masculine', 'Some people think that cooking isn''t masculine, but I completely disagree.', '有些人认为做饭没有男子气概,但我完全不同意。', 'masculine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gorgeous-1', 'gorgeous', 'The view from our hotel room was absolutely gorgeous at sunset.', '日落时,从酒店房间看到的景色美极了。', 'gorgeous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('delighted-1', 'delighted', 'I was delighted when I found out I had got the job.', '得知自己得到这份工作时,我非常高兴。', 'delighted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thrilled-1', 'thrilled', 'My parents were thrilled when I told them I was getting married.', '我告诉父母我要结婚时,他们非常激动。', 'thrilled');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('satisfied-1', 'satisfied', 'I''m pretty satisfied with my life in the city at the moment.', '我目前对城市生活挺满意的。', 'satisfied');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('content-1', 'content', 'I''m pretty content with my life at the moment, to be honest.', '说实话,我对现在的生活挺满足的。', 'content');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grateful-1', 'grateful', 'I''m really grateful to my teacher for helping me through that difficult year.', '我非常感激老师帮我度过了那艰难的一年。', 'grateful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('proud-1', 'proud', 'I felt so proud when my son won a prize at school.', '我儿子在学校获奖时,我感到非常自豪。', 'proud');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relieved-1', 'relieved', 'I was so relieved when I finally found my lost passport.', '我终于找到丢失的护照时,真是松了一口气。', 'relieved');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relaxed-1', 'relaxed', 'I always feel relaxed after a long walk in the countryside.', '在乡间走了很久之后,我总是感到很放松。', 'relaxed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amazed-1', 'amazed', 'I was amazed by how friendly people were when I visited Japan.', '我去日本时,对人们的友好感到惊讶。', 'amazed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('astonished-1', 'astonished', 'I was astonished to see how much the town had changed.', '看到小镇变化这么大,我很震惊。', 'astonished');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impressed-1', 'impressed', 'I was really impressed by the service at that little restaurant.', '那家小餐馆的服务给我留下了深刻印象。', 'impressed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fascinated-1', 'fascinated', 'I''ve been fascinated by space ever since I was a little kid.', '我从小就对太空着迷。', 'fascinated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nostalgic-1', 'nostalgic', 'Old songs from my school days always make me feel nostalgic.', '上学时的老歌总让我感到怀旧。', 'nostalgic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disappointed-1', 'disappointed', 'I was really disappointed when the concert was cancelled at the last minute.', '音乐会在最后一刻取消时,我非常失望。', 'disappointed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('frustrated-1', 'frustrated', 'I get really frustrated when my phone stops working in the middle of a call.', '通话时手机突然没反应,我会特别沮丧。', 'frustrated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('annoyed-1', 'annoyed', 'I get annoyed when people talk loudly on their phones on the train.', '有人在火车上大声打电话时,我会很恼火。', 'annoyed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('embarrassed-1', 'embarrassed', 'I felt so embarrassed when I forgot my boss''s name at the party.', '在派对上我忘了老板的名字,感到特别尴尬。', 'embarrassed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nervous-1', 'nervous', 'I always feel nervous before speaking in front of a large group.', '在一大群人面前讲话前,我总是很紧张。', 'nervous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anxious-1', 'anxious', 'I was quite anxious about moving to a new city on my own.', '一个人搬到新城市,我当时挺焦虑的。', 'anxious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stressed-1', 'stressed', 'I get really stressed when I have too many deadlines at once.', '同时有太多截止日期时,我会感到压力特别大。', 'stressed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exhausted-1', 'exhausted', 'I was completely exhausted after the long flight from Sydney.', '从悉尼飞了很久之后,我完全筋疲力尽了。', 'exhausted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('homesick-1', 'homesick', 'I felt homesick during my first few weeks at university.', '上大学的头几周,我很想家。', 'homesick');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jealous-1', 'jealous', 'I was a bit jealous when my friend got a much better job.', '朋友找到一份好得多的工作时,我有点嫉妒。', 'jealous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('regret-1', 'regret', 'I regret not learning to play an instrument when I was younger.', '我后悔年轻时没有学一门乐器。', 'regret');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('appreciate-1', 'appreciate', 'I didn''t appreciate my hometown until I moved far away from it.', '直到搬到很远的地方,我才懂得欣赏我的家乡。', 'appreciate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('admire-1', 'admire', 'What I admire most about my mum is how calm she stays.', '我最佩服妈妈的一点是她总能保持冷静。', 'admire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cherish-1', 'cherish', 'I really cherish the time I spent with my grandparents as a child.', '我非常珍惜小时候和祖父母一起度过的时光。', 'cherish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-keen-on-1', 'be-keen-on', 'I''m not really keen on sports, but I do enjoy watching football.', '我不太热衷运动,但确实喜欢看足球。', 'keen on');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-fond-of-1', 'be-fond-of', 'I''ve always been fond of old films, especially black and white ones.', '我一直喜欢老电影,特别是黑白片。', 'fond of');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('be-passionate-about-1', 'be-passionate-about', 'I''m passionate about cooking and try a new recipe every weekend.', '我对烹饪充满热情,每个周末都尝试新食谱。', 'passionate about');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cant-stand-doing-sth-1', 'cant-stand-doing-sth', 'I can''t stand waiting in long queues, especially when I''m in a hurry.', '我无法忍受排长队,尤其是赶时间的时候。', 'can''t stand');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unforgettable-1', 'unforgettable', 'Our trip to the mountains last year was an unforgettable experience.', '去年的山区之旅是一次难忘的经历。', 'unforgettable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('memorable-1', 'memorable', 'The most memorable meal I''ve ever had was at a tiny place in Italy.', '我吃过最难忘的一餐是在意大利的一家小店。', 'memorable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('meaningful-1', 'meaningful', 'I think it''s more meaningful to give a handmade present than an expensive one.', '我觉得送手工礼物比送昂贵的礼物更有意义。', 'meaningful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rewarding-1', 'rewarding', 'Teaching young children can be tiring, but it''s a really rewarding job.', '教幼儿可能很累,但这是一份很有回报的工作。', 'rewarding');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fulfilling-1', 'fulfilling', 'I''d like a fulfilling job, even if the pay isn''t very high.', '我想要一份有成就感的工作,即使薪水不是很高。', 'fulfilling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('challenging-1', 'challenging', 'Learning to drive was challenging at first, but I soon got used to it.', '学开车一开始很有挑战性,但我很快就适应了。', 'challenging');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tedious-1', 'tedious', 'I find filling in forms really tedious, so I always leave it until last.', '我觉得填表特别乏味,所以总是留到最后。', 'tedious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('monotonous-1', 'monotonous', 'My first job was quite monotonous, doing the same thing every day.', '我的第一份工作挺单调的,每天都做同样的事。', 'monotonous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sentimental-1', 'sentimental', 'I''m quite sentimental and keep all the cards that friends have given me.', '我挺多愁善感的,朋友送的卡片我都留着。', 'sentimental');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('indifferent-1', 'indifferent', 'I''m pretty indifferent to fashion and just wear whatever is clean.', '我对时尚挺无所谓的,有什么干净的就穿什么。', 'indifferent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('desperate-1', 'desperate', 'I was desperate for a coffee after getting up at five that morning.', '那天早上五点就起床,我特别想喝杯咖啡。', 'desperate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enjoyable-1', 'enjoyable', 'We had a really enjoyable afternoon walking along the river.', '我们沿着河边散步,度过了一个非常愉快的下午。', 'enjoyable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refreshing-1', 'refreshing', 'It''s refreshing to meet people who really listen to what you say.', '遇到真正倾听你说话的人,感觉令人耳目一新。', 'refreshing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('depressing-1', 'depressing', 'I find the weather in November quite depressing, because it''s so dark.', '我觉得十一月的天气挺让人沮丧的,因为天太暗了。', 'depressing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('appealing-1', 'appealing', 'Working from home sounds appealing, but I''d probably miss my colleagues.', '在家工作听起来很有吸引力,但我可能会想念同事。', 'appealing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('incredible-1', 'incredible', 'The view from the top of the mountain was absolutely incredible.', '从山顶看到的景色真是太棒了。', 'incredible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ridiculous-1', 'ridiculous', 'It sounds ridiculous, but I still sleep with the same old pillow.', '听起来很可笑,但我现在还枕着那个旧枕头睡觉。', 'ridiculous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nasty-1', 'nasty', 'I had a nasty cold last winter and stayed in bed for a week.', '去年冬天我得了重感冒,在床上躺了一周。', 'nasty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bizarre-1', 'bizarre', 'I had a bizarre dream last night about flying over my old school.', '我昨晚做了个怪梦,梦见自己飞过以前的学校。', 'bizarre');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ashamed-1', 'ashamed', 'I felt ashamed of myself for shouting at my little brother.', '我对弟弟大吼之后,感到很羞愧。', 'ashamed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('furious-1', 'furious', 'My dad was furious when someone scratched his new car.', '有人刮花了爸爸的新车,他气坏了。', 'furious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('awful-1', 'awful', 'The food at that hotel was awful, so we ate out every night.', '那家酒店的饭菜很糟糕,所以我们每晚都出去吃。', 'awful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('horrible-1', 'horrible', 'We had horrible weather on holiday, and it rained for a week.', '我们度假时天气很差,下了一周的雨。', 'horrible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('miserable-1', 'miserable', 'I felt miserable for days after failing that important exam.', '那场重要的考试没通过后,我难受了好几天。', 'miserable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('uncomfortable-1', 'uncomfortable', 'I feel uncomfortable talking about money with people I don''t know well.', '和不太熟的人谈钱,我觉得不自在。', 'uncomfortable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('weird-1', 'weird', 'It felt weird going back to my old school after so many years.', '这么多年后回到以前的学校,感觉很奇怪。', 'weird');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('terrific-1', 'terrific', 'We had a terrific time at the beach with all my cousins.', '我们和所有表亲在海滩玩得开心极了。', 'terrific');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fabulous-1', 'fabulous', 'We had a fabulous meal at a tiny restaurant by the sea.', '我们在海边一家小餐馆吃了一顿特别棒的饭。', 'fabulous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('marvellous-1', 'marvellous', 'We had marvellous weather for the whole of our trip to Greece.', '我们去希腊的整个旅程天气都好极了。', 'marvellous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dreadful-1', 'dreadful', 'I had a dreadful headache and had to leave work early.', '我头疼得厉害,不得不提前下班。', 'dreadful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gloomy-1', 'gloomy', 'I always feel a bit gloomy when the days get shorter in winter.', '冬天白天变短时,我总是有点忧郁。', 'gloomy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('weary-1', 'weary', 'I was so weary after work that I went straight to bed.', '下班后我累极了,直接上床睡觉。', 'weary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grief-1', 'grief', 'It took my mum a long time to get over the grief of losing her dad.', '我妈妈花了很长时间才走出丧父的悲痛。', 'grief');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('despair-1', 'despair', 'I almost gave up in despair when I couldn''t find a job.', '找不到工作时,我几乎绝望得要放弃了。', 'despair');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('misery-1', 'misery', 'Being stuck in traffic every morning was pure misery for me.', '每天早上堵在路上对我来说简直是痛苦。', 'misery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dismay-1', 'dismay', 'To my dismay, I realised that I had left my passport at home.', '让我沮丧的是,我发现把护照忘在家里了。', 'dismay');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disgust-1', 'disgust', 'I looked at the dirty kitchen in the hostel with disgust.', '我厌恶地看着旅舍里脏兮兮的厨房。', 'disgust');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pathetic-1', 'pathetic', 'I felt a bit pathetic crying at the end of that silly film.', '看那部傻乎乎的电影看到结尾哭了,我觉得自己有点可悲。', 'pathetic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('restless-1', 'restless', 'I feel restless if I have to sit in an office all day.', '如果得整天坐在办公室,我会焦躁不安。', 'restless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rectangular-1', 'rectangular', 'We''ve got a big rectangular table in the kitchen where we all eat.', '我们厨房有一张大长方形餐桌,大家都在那儿吃饭。', 'rectangular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oval-1', 'oval', 'My favourite mirror is an old oval one that belonged to my grandmother.', '我最喜欢的镜子是一面老式椭圆镜,是我奶奶留下的。', 'oval');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('triangular-1', 'triangular', 'We have a small triangular garden behind our house, full of flowers.', '我们屋后有个小小的三角形花园,种满了花。', 'triangular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('circular-1', 'circular', 'We sat around a circular table so that everyone could talk easily.', '我们围坐在圆桌旁,这样大家都方便交谈。', 'circular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cylindrical-1', 'cylindrical', 'My pencil case is a small cylindrical tin that I''ve had for years.', '我的铅笔盒是一个用了多年的小圆柱形铁盒。', 'cylindrical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spherical-1', 'spherical', 'I bought a little spherical lamp that looks just like the Moon.', '我买了一盏小球形灯,看起来就像月亮。', 'spherical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compact-1', 'compact', 'My new camera is really compact, so it fits easily in my pocket.', '我的新相机很小巧,很容易放进口袋。', 'compact');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('portable-1', 'portable', 'I bought a portable speaker to take to the beach with my friends.', '我买了一个便携音箱,和朋友带去海滩用。', 'portable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lightweight-1', 'lightweight', 'This laptop is very lightweight, which is great because I travel a lot.', '这台笔记本很轻便,对我这个经常出差的人来说太好了。', 'lightweight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bulky-1', 'bulky', 'My old suitcase was so bulky that I could hardly carry it.', '我的旧手提箱太笨重了,几乎拎不动。', 'bulky');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fragile-1', 'fragile', 'Be careful with that vase, because it''s very old and fragile.', '小心那个花瓶,它很古老,也很易碎。', 'fragile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('durable-1', 'durable', 'These boots are really durable, and I''ve worn them for ten years.', '这双靴子很耐用,我已经穿了十年了。', 'durable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sturdy-1', 'sturdy', 'We need a sturdy table, because the children are always climbing on it.', '我们需要一张结实的桌子,因为孩子们总爬上去。', 'sturdy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('smooth-1', 'smooth', 'I love the smooth feel of this old wooden box.', '我喜欢这个旧木盒光滑的手感。', 'smooth');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rough-1', 'rough', 'The walls of the cottage are made of rough stone.', '这间小屋的墙是用粗糙的石头砌成的。', 'rough');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rough-2', 'rough', 'I''ve got a rough idea of where I''d like to go next summer.', '我对明年夏天想去哪里有个大致的想法。', 'rough');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transparent-1', 'transparent', 'I keep my photos in a transparent box so that I can see them.', '我把照片放在透明的盒子里,这样就能看到它们。', 'transparent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shiny-1', 'shiny', 'I bought a shiny red bike with the money from my first job.', '我用第一份工作的钱买了一辆闪亮的红色自行车。', 'shiny');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('colourful-1', 'colourful', 'I love the colourful houses along the seafront in my hometown.', '我喜欢家乡海滨那些色彩丰富的房子。', 'colourful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vivid-1', 'vivid', 'I still have vivid memories of my first day at school.', '我至今还清晰地记得上学第一天。', 'vivid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pale-1', 'pale', 'The walls in my bedroom are painted a pale shade of green.', '我卧室的墙刷成了浅绿色。', 'pale');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('beige-1', 'beige', 'I''ve got a beige coat that goes with almost everything I own.', '我有一件米色大衣,几乎能配我所有的衣服。', 'beige');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('navy-1', 'navy', 'I usually wear a navy jacket to work, because it looks smart.', '我上班通常穿一件藏青色夹克,因为看起来很精神。', 'navy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('striped-1', 'striped', 'My favourite shirt is an old blue and white striped one.', '我最喜欢的衬衫是一件旧的蓝白条纹衫。', 'striped');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('checked-1', 'checked', 'My dad always wears a checked shirt when he goes fishing.', '我爸爸钓鱼时总穿格子衬衫。', 'checked');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('leather-1', 'leather', 'I''ve got an old leather bag that I bought in Italy years ago.', '我有一个多年前在意大利买的旧皮包。', 'leather');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cotton-1', 'cotton', 'I usually wear cotton shirts in summer because they feel so comfortable.', '我夏天通常穿棉衬衫,因为穿着很舒服。', 'cotton');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wool-1', 'wool', 'My mum knitted me a thick wool jumper for the winter.', '我妈妈给我织了一件厚羊毛衫过冬。', 'wool');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('silk-1', 'silk', 'I bought a beautiful silk scarf for my mother when I was in Thailand.', '在泰国时,我给妈妈买了一条漂亮的丝绸围巾。', 'silk');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('linen-1', 'linen', 'Linen trousers are perfect for hot weather, but they crease easily.', '亚麻裤子很适合热天穿,但容易起皱。', 'Linen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ceramic-1', 'ceramic', 'I bought a little ceramic bowl from a local artist on my holiday.', '度假时,我从当地一位艺术家那里买了一只小陶瓷碗。', 'ceramic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('porcelain-1', 'porcelain', 'My grandmother has a set of fine porcelain cups she never uses.', '我奶奶有一套精美的瓷杯,她从来不用。', 'porcelain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wooden-1', 'wooden', 'My grandfather made this little wooden horse for me when I was three.', '我三岁时,爷爷给我做了这匹小木马。', 'wooden');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plastic-1', 'plastic', 'I try not to buy drinks in plastic bottles these days.', '现在我尽量不买塑料瓶装的饮料。', 'plastic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('handmade-1', 'handmade', 'I prefer handmade gifts, because they show that someone really cares.', '我更喜欢手工礼物,因为它们显示对方真的用心了。', 'handmade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('machine-made-1', 'machine-made', 'Machine-made furniture is cheaper, but it doesn''t last as long.', '机器制造的家具更便宜,但没那么耐用。', 'Machine-made');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exquisite-1', 'exquisite', 'The temple has exquisite wooden carvings that took years to complete.', '这座寺庙有精致的木雕,花了好几年才完成。', 'exquisite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('delicate-1', 'delicate', 'I have to be careful with this delicate old necklace.', '我得小心对待这条精致的旧项链。', 'delicate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decorative-1', 'decorative', 'These plates are just decorative, so we never actually eat off them.', '这些盘子只是装饰用的,我们从不真正用来吃饭。', 'decorative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vintage-1', 'vintage', 'I love looking for vintage clothes in the little shops near my flat.', '我喜欢在公寓附近的小店里淘复古衣服。', 'vintage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brand-new-1', 'brand-new', 'I saved for a year to buy a brand-new laptop.', '我攒了一年钱才买了一台全新的笔记本电脑。', 'brand-new');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('worn-out-1', 'worn-out', 'These old trainers are completely worn-out, so I need a new pair.', '这双旧运动鞋完全穿破了,我得买双新的。', 'worn-out');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sentimental-value-1', 'sentimental-value', 'This cheap old watch has great sentimental value because it was my father''s.', '这块便宜的旧手表很有情感价值,因为它是我父亲的。', 'sentimental value');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('valuable-1', 'valuable', 'My most valuable possession is a ring that belonged to my grandmother.', '我最贵重的东西是奶奶留下的一枚戒指。', 'valuable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('priceless-1', 'priceless', 'My childhood photos are priceless to me, so I keep them safe.', '童年的照片对我来说是无价的,所以我小心保管。', 'priceless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('affordable-1', 'affordable', 'The restaurants near my university are pretty affordable for students.', '我们大学附近的餐馆对学生来说挺实惠的。', 'affordable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pricey-1', 'pricey', 'That café is a bit pricey, but the coffee is really good.', '那家咖啡馆有点贵,但咖啡确实很好喝。', 'pricey');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('value-for-money-1', 'value-for-money', 'The set lunch at that restaurant is really good value for money.', '那家餐馆的午市套餐真是物有所值。', 'value for money');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('luxurious-1', 'luxurious', 'The hotel was far more luxurious than anything I had stayed in before.', '那家酒店比我以前住过的任何地方都奢华得多。', 'luxurious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carved-1', 'carved', 'My parents have a beautifully carved wooden chest in their living room.', '我父母的客厅里有一个雕刻精美的木箱。', 'carved');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('garment-1', 'garment', 'That jacket is my favourite garment, and I''ve had it since I was eighteen.', '那件夹克是我最喜欢的衣服,我十八岁起就有了。', 'garment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gown-1', 'gown', 'My friend wore a long white gown at her graduation ball.', '我朋友在毕业舞会上穿了一件白色长礼服。', 'gown');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('uniform-1', 'uniform', 'I had to wear a dark blue uniform when I was at school.', '我上学时必须穿深蓝色的制服。', 'uniform');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('apron-1', 'apron', 'My dad puts on a funny apron whenever he cooks for the family.', '我爸爸给家人做饭时总穿着一条搞笑的围裙。', 'apron');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('collar-1', 'collar', 'I don''t like shirts with a tight collar, as they feel uncomfortable.', '我不喜欢领口紧的衬衫,穿着不舒服。', 'collar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sleeve-1', 'sleeve', 'I usually roll up the sleeves of my shirt when it gets hot.', '天热时我通常把衬衫袖子卷起来。', 'sleeves');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shawl-1', 'shawl', 'My grandmother always wore a warm woollen shawl around her shoulders.', '我奶奶肩上总披着一条暖和的羊毛披肩。', 'shawl');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cheongsam-1', 'cheongsam', 'My mother wore a red cheongsam at my cousin''s wedding last year.', '去年表姐的婚礼上,我妈妈穿了一件红色旗袍。', 'cheongsam');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lace-1', 'lace', 'My wedding dress had beautiful lace on the sleeves and around the neck.', '我的婚纱袖子和领口都有漂亮的蕾丝。', 'lace');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nylon-1', 'nylon', 'I''ve got a light nylon jacket that''s great for walking in the rain.', '我有一件轻便的尼龙夹克,很适合雨中行走。', 'nylon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cashmere-1', 'cashmere', 'My aunt gave me a soft cashmere scarf for my last birthday.', '上次生日,我阿姨送了我一条柔软的羊绒围巾。', 'cashmere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scarlet-1', 'scarlet', 'She arrived at the party in a bright scarlet dress and silver shoes.', '她穿着鲜艳的猩红色连衣裙和银色鞋子来到派对。', 'scarlet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ivory-1', 'ivory', 'I''ve got an old piano with yellowed ivory keys that belonged to my grandfather.', '我有一架老钢琴,琴键是泛黄的象牙,是爷爷留下的。', 'ivory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amber-1', 'amber', 'My aunt gave me a lovely necklace made of amber from Poland.', '我阿姨送了我一条来自波兰的漂亮琥珀项链。', 'amber');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('khaki-1', 'khaki', 'I usually wear khaki trousers and a plain shirt when I go hiking.', '我去徒步时通常穿卡其色裤子和素色衬衫。', 'khaki');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lilac-1', 'lilac', 'We painted our daughter''s bedroom a lovely shade of lilac.', '我们把女儿的卧室刷成了可爱的淡紫色。', 'lilac');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('family-name-1', 'family-name', 'In my country, the family name always comes before the given name.', '在我的国家,姓氏总是放在名字前面。', 'family name');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('given-name-1', 'given-name', 'My given name was chosen by my grandfather and means ''bright''.', '我的名字是爷爷取的,意思是“明亮”。', 'given name');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('neat-1', 'neat', 'I like to keep my desk neat, or I can''t concentrate at all.', '我喜欢保持书桌整洁,否则根本无法集中精力。', 'neat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cord-1', 'cord', 'I keep tripping over the cord from the lamp in my bedroom.', '我老是被卧室台灯的电线绊倒。', 'cord');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bucket-1', 'bucket', 'When I was little, I''d take a bucket to the beach and collect shells.', '我小时候常提着一个桶去海滩捡贝壳。', 'bucket');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bundle-1', 'bundle', 'I found a bundle of old letters from my parents in the attic.', '我在阁楼上发现了一捆父母的旧信。', 'bundle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('texture-1', 'texture', 'I like the rough texture of this old wooden table in my kitchen.', '我喜欢厨房这张旧木桌粗糙的质地。', 'texture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scent-1', 'scent', 'The scent of fresh bread always reminds me of my childhood home.', '新鲜面包的香味总让我想起童年的家。', 'scent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('odour-1', 'odour', 'There''s a strange odour in the kitchen, so I think something has gone bad.', '厨房里有一股奇怪的气味,我想是有什么东西坏了。', 'odour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crisp-1', 'crisp', 'I love the crisp apples that we pick at my uncle''s farm.', '我喜欢在叔叔农场摘的脆苹果。', 'crisp');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cloth-1', 'cloth', 'I use an old cloth to clean the windows in my flat.', '我用一块旧布擦公寓的窗户。', 'cloth');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clothing-1', 'clothing', 'I spend very little money on clothing because I don''t care about fashion.', '我在服装上花钱很少,因为我不在乎时尚。', 'clothing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('belt-1', 'belt', 'My dad gave me this leather belt when I got my first job.', '我得到第一份工作时,爸爸送了我这条皮腰带。', 'belt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boot-1', 'boot', 'I bought a pair of warm winter boots before moving to Canada.', '搬到加拿大之前,我买了一双保暖的冬靴。', 'boots');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mask-1', 'mask', 'We wore masks and funny costumes to the party at the end of term.', '我们戴着面具、穿着搞笑的服装参加了期末派对。', 'masks');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('perfume-1', 'perfume', 'I can always tell when my mum has been in a room from her perfume.', '凭香水味,我总能知道妈妈是否来过这个房间。', 'perfume');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jewellery-1', 'jewellery', 'I don''t wear much jewellery, just a watch and a simple ring.', '我不戴什么首饰,只有一块手表和一枚简单的戒指。', 'jewellery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('velvet-1', 'velvet', 'My grandmother''s old sofa was covered in dark green velvet.', '我奶奶的旧沙发上覆盖着深绿色的天鹅绒。', 'velvet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ornament-1', 'ornament', 'I keep a little glass ornament from Venice on my bedroom shelf.', '我卧室架子上放着一件来自威尼斯的小玻璃装饰品。', 'ornament');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rim-1', 'rim', 'There''s a small crack in the rim of my favourite coffee cup.', '我最喜欢的咖啡杯边缘有一道小裂纹。', 'rim');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('glue-1', 'glue', 'I broke the handle of my favourite mug, so I fixed it with glue.', '我把最喜欢的杯子把手弄断了,就用胶水粘好了。', 'glue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('patch-1', 'patch', 'My jeans have a big patch on one knee, but I still love them.', '我的牛仔裤一条膝盖上有个大补丁,但我还是很喜欢它们。', 'patch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('knot-1', 'knot', 'I''m hopeless at tying a tie, and the knot always looks terrible.', '我特别不会打领带,结总是打得很难看。', 'knot');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('strap-1', 'strap', 'The strap on my bag broke while I was running for the bus.', '我跑着赶公交时,包带断了。', 'strap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fancy-1', 'fancy', 'We went to a fancy restaurant to celebrate my parents'' anniversary.', '我们去一家高档餐厅庆祝父母的结婚纪念日。', 'fancy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bustling-1', 'bustling', 'I love walking through the bustling market near my flat on Saturdays.', '周六我喜欢穿过公寓附近熙熙攘攘的市场。', 'bustling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vibrant-1', 'vibrant', 'What I like most about my hometown is its vibrant night market.', '我最喜欢家乡的一点是它充满活力的夜市。', 'vibrant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lively-1', 'lively', 'The old town is really lively in the evenings, with music everywhere.', '老城的晚上非常热闹,到处都是音乐。', 'lively');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crowded-1', 'crowded', 'I try to avoid the crowded shops in the city centre at weekends.', '周末我尽量避开市中心拥挤的商店。', 'crowded');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peaceful-1', 'peaceful', 'My grandparents live in a peaceful village surrounded by rice fields.', '我的祖父母住在一个被稻田环绕的宁静村庄。', 'peaceful');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tranquil-1', 'tranquil', 'I love sitting by the tranquil lake near my home after work.', '我喜欢下班后坐在家附近宁静的湖边。', 'tranquil');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('serene-1', 'serene', 'The temple garden is so serene that I always feel calm there.', '寺庙花园非常安详,我在那里总感到平静。', 'serene');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('picturesque-1', 'picturesque', 'We stayed in a picturesque village with old stone houses by a river.', '我们住在一个风景如画的村庄,河边都是古老的石屋。', 'picturesque');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scenic-1', 'scenic', 'We took the scenic route along the coast instead of the motorway.', '我们走了风景优美的海岸路线,而不是高速公路。', 'scenic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('breathtaking-1', 'breathtaking', 'The view from the top of the tower was absolutely breathtaking.', '从塔顶看到的景色令人叹为观止。', 'breathtaking');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spectacular-1', 'spectacular', 'We watched a spectacular sunset from the beach on our last night.', '最后一晚,我们在海滩上看了一场壮观的日落。', 'spectacular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('magnificent-1', 'magnificent', 'The palace was magnificent, with huge rooms and beautiful gardens.', '这座宫殿宏伟壮观,有巨大的房间和美丽的花园。', 'magnificent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impressive-1', 'impressive', 'The new library in my city is a very impressive building.', '我们城市的新图书馆是一座令人印象深刻的建筑。', 'impressive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('historic-1', 'historic', 'My hometown has a historic bridge that was built about 500 years ago.', '我的家乡有一座约五百年前建造的历史古桥。', 'historic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('historical-1', 'historical', 'I enjoy reading historical novels, especially those set in ancient China.', '我喜欢读历史小说,尤其是以中国古代为背景的。', 'historical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cosmopolitan-1', 'cosmopolitan', 'It''s a very cosmopolitan city, with people from all over the world.', '这是一座非常国际化的城市,有来自世界各地的人。', 'cosmopolitan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('well-preserved-1', 'well-preserved', 'The old town is really well-preserved, and tourists love walking around it.', '老城保存得非常完好,游客们很喜欢在那里漫步。', 'well-preserved');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('run-down-1', 'run-down', 'My old neighbourhood has become a bit run-down over the last few years.', '过去几年,我以前住的社区变得有点破败了。', 'run-down');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('remote-1', 'remote', 'My uncle lives in a remote village, and it takes all day to get there.', '我叔叔住在一个偏远的村庄,要花一整天才能到。', 'remote');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('remote-2', 'remote', 'I''ve been doing remote work for two years and I really enjoy it.', '我已经远程工作两年了,我真的很喜欢。', 'remote');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('isolated-1', 'isolated', 'I''d feel too isolated living on a farm far from other people.', '住在远离人群的农场,我会觉得太与世隔绝了。', 'isolated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('well-connected-1', 'well-connected', 'My area is well-connected, with buses and trains to the city centre.', '我住的地方交通便利,有公交车和火车通往市中心。', 'well-connected');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('within-walking-distance-1', 'within-walking-distance', 'Everything I need is within walking distance of my flat.', '我需要的一切都在公寓步行可达的范围内。', 'within walking distance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hometown-1', 'hometown', 'My hometown is a small city in the south, famous for its tea.', '我的家乡是南方的一座小城,以茶闻名。', 'hometown');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('downtown-1', 'downtown', 'I live about ten minutes from downtown, so getting around is easy.', '我住的地方离市中心大约十分钟,出行很方便。', 'downtown');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('city-centre-1', 'city-centre', 'I don''t usually drive into the city centre because parking is so expensive.', '我通常不开车去市中心,因为停车太贵了。', 'city centre');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('countryside-1', 'countryside', 'I''d love to live in the countryside when I''m older.', '我年纪大了以后很想住在乡村。', 'countryside');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seaside-1', 'seaside', 'We used to go to the seaside every summer when I was young.', '我小时候每年夏天都去海边。', 'seaside');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resort-1', 'resort', 'We spent a week at a ski resort in the mountains last winter.', '去年冬天,我们在山里的滑雪胜地待了一周。', 'resort');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('street-food-1', 'street-food', 'The best thing about visiting Bangkok was definitely the street food.', '去曼谷最棒的事情无疑是街头小吃。', 'street food');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('delicacy-1', 'delicacy', 'This spicy fish soup is a local delicacy in my part of the country.', '这种辣鱼汤是我们这个地区的当地美味佳肴。', 'delicacy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('local-speciality-1', 'local-speciality', 'You really should try the local speciality when you visit my hometown.', '来我家乡时,你真应该尝尝当地特产。', 'local speciality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nightlife-1', 'nightlife', 'The nightlife in my city is great, with lots of bars and live music.', '我们城市的夜生活很棒,有很多酒吧和现场音乐。', 'nightlife');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flourishing-1', 'flourishing', 'There''s a flourishing music scene in the city where I live now.', '我现在住的城市音乐氛围非常活跃。', 'flourishing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('birthplace-1', 'birthplace', 'My hometown is the birthplace of a very famous Chinese poet.', '我的家乡是一位著名中国诗人的出生地。', 'birthplace');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foothill-1', 'foothill', 'We spent the afternoon walking in the foothills near my grandparents'' village.', '我们下午在祖父母村子附近的山麓散步。', 'foothills');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('border-1', 'border', 'My hometown is right on the border, so many people there speak two languages.', '我的家乡就在边境上,所以那里很多人会说两种语言。', 'border');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('teahouse-1', 'teahouse', 'My grandfather likes to meet his old friends at the local teahouse.', '我爷爷喜欢在当地的茶馆和老朋友见面。', 'teahouse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('villager-1', 'villager', 'Every villager came out to welcome us when we arrived.', '我们到达时,每个村民都出来欢迎我们。', 'villager');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('noble-1', 'noble', 'Our local museum has a huge painting of a noble family from the past.', '我们当地的博物馆有一幅巨大的画,画的是过去的一个高贵家族。', 'noble');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unsophisticated-1', 'unsophisticated', 'The food there is simple and unsophisticated, but it tastes really good.', '那里的食物简单淳朴,但味道很好。', 'unsophisticated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('surroundings-1', 'surroundings', 'I work better in quiet surroundings, so I often go to the library.', '我在安静的环境中工作效率更高,所以常去图书馆。', 'surroundings');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('haven-1', 'haven', 'For me, the local park is a haven of peace in a noisy city.', '对我来说,当地的公园是喧闹城市中一处宁静的避风港。', 'haven');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('splendid-1', 'splendid', 'We had a splendid view of the mountains from our hotel window.', '从酒店窗户望出去,群山的景色壮丽极了。', 'splendid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pastime-1', 'pastime', 'Reading has always been my favourite pastime, especially on rainy days.', '阅读一直是我最喜欢的消遣,尤其是下雨天。', 'pastime');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('leisure-1', 'leisure', 'I don''t have much leisure time at the moment because of my job.', '由于工作的原因,我目前没有多少闲暇时间。', 'leisure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spare-time-1', 'spare-time', 'In my spare time, I like to go swimming or read a good book.', '空闲时间我喜欢游泳或读一本好书。', 'spare time');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recreation-1', 'recreation', 'For recreation, I usually go cycling along the river at weekends.', '周末休闲时,我通常沿着河边骑车。', 'recreation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('entertainment-1', 'entertainment', 'There isn''t much entertainment in my village, apart from one small cinema.', '我们村没什么娱乐,只有一家小电影院。', 'entertainment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amusement-1', 'amusement', 'The children watched the old man''s card tricks with great amusement.', '孩子们津津有味地看着老人变纸牌戏法。', 'amusement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amusement-park-1', 'amusement-park', 'We went to an amusement park for my son''s tenth birthday.', '我们去游乐园庆祝儿子十岁生日。', 'amusement park');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('theme-park-1', 'theme-park', 'I went on every ride at the theme park, even the scary ones.', '我在主题公园玩了每一个项目,连吓人的都玩了。', 'theme park');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outdoor-activities-1', 'outdoor-activities', 'I prefer outdoor activities like hiking to going to the gym.', '比起去健身房,我更喜欢徒步这样的户外活动。', 'outdoor activities');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('indoor-1', 'indoor', 'When it rains, I usually go to an indoor swimming pool near my flat.', '下雨时,我通常去公寓附近的室内游泳池。', 'indoor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jogging-1', 'jogging', 'I go jogging in the park near my home three times a week.', '我每周三次去家附近的公园慢跑。', 'jogging');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('workout-1', 'workout', 'I do a short workout at home before I start work each morning.', '每天早上开始工作前,我都在家做一次短时间的锻炼。', 'workout');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mountaineering-1', 'mountaineering', 'Mountaineering is too dangerous for me, but I enjoy walking in the hills.', '登山对我来说太危险了,但我喜欢在山丘上散步。', 'Mountaineering');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('camping-1', 'camping', 'My family used to go camping by the lake every summer.', '我家以前每年夏天都去湖边露营。', 'camping');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gaming-1', 'gaming', 'I spent far too much time gaming when I was at university.', '我上大学时花了太多时间玩电子游戏。', 'gaming');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('novel-1', 'novel', 'The last novel I read was about a family living on a small island.', '我最近读的一本小说讲的是住在小岛上的一家人。', 'novel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('biography-1', 'biography', 'I''ve just finished a biography of a famous Chinese scientist.', '我刚读完一本关于一位著名中国科学家的传记。', 'biography');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('autobiography-1', 'autobiography', 'I really enjoyed the singer''s autobiography, as it was so honest.', '我很喜欢这位歌手的自传,因为写得很坦诚。', 'autobiography');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('genre-1', 'genre', 'My favourite film genre is comedy, because it always cheers me up.', '我最喜欢的电影类型是喜剧,因为它总能让我开心起来。', 'genre');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plot-1', 'plot', 'The plot of the film was so confusing that I got lost halfway through.', '这部电影的情节太混乱了,我看到一半就看不懂了。', 'plot');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('character-1', 'character', 'My favourite character in the series is a funny old doctor.', '这部剧里我最喜欢的角色是一位风趣的老医生。', 'character');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('protagonist-1', 'protagonist', 'The protagonist of the book is a young girl who runs away from home.', '这本书的主人公是一个离家出走的小女孩。', 'protagonist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('series-1', 'series', 'I watched the whole series in just one weekend.', '我只用一个周末就看完了整部剧。', 'series');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('episode-1', 'episode', 'I watch one episode of my favourite show every night before bed.', '我每晚睡前看一集最喜欢的节目。', 'episode');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sitcom-1', 'sitcom', 'I love watching an old American sitcom when I need a laugh.', '想笑的时候,我喜欢看一部老的美国情景喜剧。', 'sitcom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('soap-opera-1', 'soap-opera', 'My mum watches the same soap opera every evening after dinner.', '我妈妈每天晚饭后都看同一部肥皂剧。', 'soap opera');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reality-show-1', 'reality-show', 'I think that every reality show on television is a bit silly.', '我觉得电视上的每个真人秀都有点傻。', 'reality show');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thriller-1', 'thriller', 'I love a good thriller, especially one with a surprise ending.', '我喜欢好看的惊悚片,特别是结局出人意料的那种。', 'thriller');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('comedy-1', 'comedy', 'I prefer comedy to serious films, because I like to relax after work.', '比起严肃的电影,我更喜欢喜剧,因为下班后想放松。', 'comedy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('animation-1', 'animation', 'Japanese animation is really popular among young people in my country.', '日本动画在我国的年轻人中很受欢迎。', 'animation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('science-fiction-1', 'science-fiction', 'I''ve loved science fiction ever since I saw my first space film.', '自从看了第一部太空电影,我就爱上了科幻。', 'science fiction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('soundtrack-1', 'soundtrack', 'The soundtrack of that film is my favourite music to study to.', '那部电影的原声音乐是我学习时最喜欢听的。', 'soundtrack');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lyrics-1', 'lyrics', 'I can never remember the lyrics, so I just sing along badly.', '我总记不住歌词,所以只能胡乱跟着唱。', 'lyrics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('melody-1', 'melody', 'That song has such a simple melody that I can''t get it out of my head.', '那首歌的旋律很简单,我总忘不掉。', 'melody');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rhythm-1', 'rhythm', 'I have no sense of rhythm, so I''m a terrible dancer.', '我没有节奏感,所以跳舞很差劲。', 'rhythm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instrument-1', 'instrument', 'I''ve always wanted to learn a musical instrument, maybe the guitar.', '我一直想学一门乐器,也许是吉他。', 'instrument');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('classical-music-1', 'classical-music', 'I listen to classical music when I need to concentrate on my work.', '需要集中精力工作时,我会听古典音乐。', 'classical music');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pop-music-1', 'pop-music', 'I mostly listened to pop music when I was a teenager.', '我十几岁时主要听流行音乐。', 'pop music');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('live-music-1', 'live-music', 'There''s a little bar near my flat that has live music on Fridays.', '我公寓附近有一家小酒吧,周五有现场音乐。', 'live music');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('baking-1', 'baking', 'I got into baking during the holidays, and now I make bread every week.', '我假期时迷上了烘焙,现在每周都做面包。', 'baking');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('collecting-1', 'collecting', 'I''ve been collecting stamps from different countries since I was a child.', '我从小就开始收藏各国的邮票。', 'collecting');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('painting-1', 'painting', 'Painting helps me to relax after a long and busy week at work.', '忙碌工作一周后,绘画能帮助我放松。', 'Painting');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sketch-1', 'sketch', 'I usually carry a small notebook so that I can make a quick sketch.', '我通常带一个小本子,这样可以随手画张素描。', 'sketch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('calligraphy-1', 'calligraphy', 'My grandfather taught me calligraphy when I was about eight years old.', '我大约八岁时,爷爷教我书法。', 'calligraphy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('knitting-1', 'knitting', 'My mum finds knitting very relaxing, especially on cold winter evenings.', '我妈妈觉得编织很放松,尤其是在寒冷的冬夜。', 'knitting');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('routine-1', 'routine', 'My morning routine is simple: I get up, have a coffee and go for a run.', '我的早晨日常很简单:起床、喝咖啡、去跑步。', 'routine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('punctual-1', 'punctual', 'I try to be punctual, because I hate keeping other people waiting.', '我尽量守时,因为我讨厌让别人等。', 'punctual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('procrastinate-1', 'procrastinate', 'I tend to procrastinate when I have a big piece of work to do.', '有一大堆工作要做时,我往往会拖延。', 'procrastinate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('time-management-1', 'time-management', 'I''m not great at time management, so I often work late at night.', '我不太擅长时间管理,所以常常工作到深夜。', 'time management');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('morning-person-1', 'morning-person', 'I''m definitely a morning person and do my best work before lunch.', '我绝对是个早起的人,午饭前工作效率最高。', 'morning person');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('night-owl-1', 'night-owl', 'I''m a real night owl, and I rarely go to bed before one o''clock.', '我是个十足的夜猫子,很少在一点前睡觉。', 'night owl');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('social-life-1', 'social-life', 'My social life has improved a lot since I joined the hiking club.', '加入徒步俱乐部后,我的社交生活丰富了很多。', 'social life');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('get-together-1', 'get-together', 'My family has a big get-together at my parents'' house every New Year.', '每年新年,我们全家都会在父母家大聚会。', 'get-together');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('catch-up-with-1', 'catch-up-with', 'I try to catch up with my old school friends at least once a year.', '我尽量每年至少和老同学叙一次旧。', 'catch up with');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hang-out-1', 'hang-out', 'My friends and I like to hang out at a small café after class.', '我和朋友们喜欢下课后在一家小咖啡馆待着。', 'hang out');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unwind-1', 'unwind', 'I usually unwind after work by listening to music in the bath.', '下班后我通常一边泡澡一边听音乐来放松。', 'unwind');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recharge-1', 'recharge', 'I need a quiet weekend at home now and then to recharge.', '我偶尔需要在家安静地过个周末,恢复精力。', 'recharge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chess-1', 'chess', 'My grandfather taught me to play chess when I was six.', '我六岁时,爷爷教我下国际象棋。', 'chess');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('billiards-1', 'billiards', 'My friends and I sometimes play billiards at a small club near the station.', '我和朋友有时在车站附近的小俱乐部打台球。', 'billiards');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bowling-1', 'bowling', 'We went bowling for my friend''s birthday, and I was terrible at it.', '我们为朋友庆生去打保龄球,我打得很差。', 'bowling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('breaststroke-1', 'breaststroke', 'I can only swim breaststroke, but I''d really like to learn something faster.', '我只会蛙泳,但很想学点游得更快的泳姿。', 'breaststroke');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('freestyle-1', 'freestyle', 'I learned freestyle last year, and now I swim twice a week.', '我去年学了自由泳,现在每周游两次。', 'freestyle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('karaoke-1', 'karaoke', 'We often go to karaoke after work, even though none of us can sing.', '我们下班后常去唱卡拉OK,虽然谁都不会唱。', 'karaoke');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('window-shopping-1', 'window-shopping', 'On rainy days, my friends and I often go window-shopping at the mall.', '下雨天,我和朋友经常去商场逛街看橱窗。', 'window-shopping');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('snapshot-1', 'snapshot', 'I keep an old snapshot of my family on the wall above my desk.', '我书桌上方的墙上挂着一张家人的旧快照。', 'snapshot');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tripod-1', 'tripod', 'I carry a small tripod when I take photos of the night sky.', '拍夜空时,我会带一个小三脚架。', 'tripod');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foreground-1', 'foreground', 'I like photos with something interesting in the foreground, such as flowers.', '我喜欢前景有趣的照片,比如前景是花朵。', 'foreground');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('album-1', 'album', 'My parents still keep an old photo album from their wedding.', '我父母还保留着一本他们婚礼的旧相册。', 'album');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('waltz-1', 'waltz', 'My parents learned to waltz before their wedding, and they still dance sometimes.', '我父母婚前学了华尔兹,现在有时还会跳。', 'waltz');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tango-1', 'tango', 'My friend and I took a tango class, but we were both terrible.', '我和朋友上过一节探戈课,但我们俩都跳得很差。', 'tango');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jazz-1', 'jazz', 'I started listening to jazz when I went to a small club in New York.', '我去纽约一家小俱乐部后开始听爵士乐。', 'jazz');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('puzzle-1', 'puzzle', 'I do a crossword puzzle in the newspaper every morning on the train.', '我每天早上在火车上做报纸上的填字谜题。', 'puzzle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('puzzle-2', 'puzzle', 'It puzzles me why people spend so much money on designer clothes.', '我不明白人们为什么花这么多钱买名牌衣服。', 'puzzles');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('socialise-1', 'socialise', 'I like to socialise with my colleagues after work on Fridays.', '我喜欢周五下班后和同事们交往聚会。', 'socialise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('comic-1', 'comic', 'I used to read comic books under the blanket when I was a kid.', '我小时候常躲在被子里看漫画书。', 'comic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trick-1', 'trick', 'My uncle taught me a card trick that I still use at parties.', '我叔叔教了我一个纸牌戏法,我现在还在派对上用。', 'trick');
